//! WaveNet A1 per-layer `kernel_sizes` geometry parity.
//!
//! Validates the canonical NAMCore per-layer kernel contract
//! (`NAM/wavenet/model.cpp:1003-1032`) against three independent references:
//!
//! 1. the production f32 engine vs the NumPy f64 anchor,
//! 2. the Rust f64 reference oracle vs the same NumPy f64 anchor,
//! 3. the live pinned `namcore_render` (C++) vs the prewarmed Rust engine.
//!
//! The fixture is generated by
//! `tests/fixtures/generate_wavenet_geometry_fixtures.py`; each layer array
//! uses distinct kernels per layer while keeping the legacy scalar
//! `kernel_size` contract as the homogeneous fallback.

use super::common::*;
use neural_amp_modeler_rs::loader::dispatcher::build_model;
use neural_amp_modeler_rs::loader::nam_json::parse::parse_nam_json;
use neural_amp_modeler_rs::loader::nam_json::{WavenetTopologyResult, get_wavenet_topology};
use neural_amp_modeler_rs::models::NamModel;
use neural_amp_modeler_rs::testing::reference_oracle::{
    PrecisionConfig, compute_esr_f64, esr_to_db_f64, oracle_forward,
};

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

use crate::common::alloc_audit::{TrackingGuard, get_alloc_count};

const FIXTURE: &str = "wavenet_per_layer_kernels";
const BLOCK: usize = 64;

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn models_dir() -> PathBuf {
    fixtures_dir().join("models")
}

fn anchors_dir() -> PathBuf {
    fixtures_dir().join("f64_anchors")
}

fn fixture_json() -> String {
    fs::read_to_string(models_dir().join(format!("{FIXTURE}.nam"))).expect("read geometry fixture")
}

fn load_f64_binary(path: &Path) -> Vec<f64> {
    let mut f = fs::File::open(path).expect("open f64 binary");
    let mut buf = [0u8; 4];
    f.read_exact(&mut buf).expect("read count");
    let n = u32::from_le_bytes(buf) as usize;
    let mut data = Vec::with_capacity(n);
    let mut sample = [0u8; 8];
    for _ in 0..n {
        f.read_exact(&mut sample).expect("read sample");
        data.push(f64::from_le_bytes(sample));
    }
    data
}

fn input_f32() -> Vec<f32> {
    load_f64_binary(&anchors_dir().join("wavenet_geometry_256_input.bin"))
        .iter()
        .map(|&v| v as f32)
        .collect()
}

fn process_in_blocks(model: &mut dyn NamModel, input: &[f32], output: &mut [f32]) {
    let mut pos = 0;
    while pos < input.len() {
        let end = (pos + BLOCK).min(input.len());
        model.process(&input[pos..end], &mut output[pos..end]);
        pos = end;
    }
}

#[test]
fn test_per_layer_kernels_geometry_contract() {
    let data = parse_nam_json(&fixture_json()).expect("parse fixture");
    let WavenetTopologyResult::Free(geom) = get_wavenet_topology(&data) else {
        panic!("{FIXTURE}: expected a free-geometry WaveNet A1");
    };

    assert_eq!(geom.layer_kernel_sizes, vec![vec![2, 3, 1], vec![3, 2, 1]]);
    assert_eq!(geom.kernel_sizes, vec![2, 3]);
    assert_eq!(geom.kernel_size, 2);
    assert_eq!(geom.dilations, vec![vec![1, 2, 3], vec![1, 2, 4]]);

    let per_layer = [(2usize, 1usize), (3, 2), (1, 3), (3, 1), (2, 2), (1, 4)];
    let expected_rf: usize = per_layer
        .iter()
        .map(|&(k, d)| k.saturating_sub(1) * d)
        .sum();
    assert_eq!(geom.receptive_field(), expected_rf, "per-layer RF");
}

#[test]
fn test_per_layer_kernels_engine_matches_f64_anchor() {
    let input = input_f32();
    let data = parse_nam_json(&fixture_json()).expect("parse fixture");
    let mut model = build_model(&data).expect("build model");

    // Zero-state engine output (no prewarm) vs the f64 zero-history anchor.
    let mut output = vec![0.0f32; input.len()];
    process_in_blocks(model.as_mut(), &input, &mut output);

    let anchor = load_f64_binary(&anchors_dir().join(format!("{FIXTURE}_256_f64.bin")));
    let output_f64: Vec<f64> = output.iter().map(|&v| v as f64).collect();
    let esr = compute_esr_f64(&output_f64, &anchor);
    eprintln!(
        "[Geometry] {FIXTURE}: engine f32 vs NumPy f64 ESR={esr:.3e} ({:.1} dB)",
        esr_to_db_f64(esr)
    );
    assert!(esr < 1e-9, "engine/f64 ESR {esr:.3e} exceeds 1e-9");
}

#[test]
fn test_per_layer_kernels_rust_oracle_matches_python_anchor() {
    let input = load_f64_binary(&anchors_dir().join("wavenet_geometry_256_input.bin"));
    let data = parse_nam_json(&fixture_json()).expect("parse fixture");
    let oracle = oracle_forward(&data, &input, &PrecisionConfig::default());
    let anchor = load_f64_binary(&anchors_dir().join(format!("{FIXTURE}_256_f64.bin")));
    let esr = compute_esr_f64(&oracle, &anchor);
    eprintln!(
        "[Geometry] {FIXTURE}: Rust f64 oracle vs NumPy anchor ESR={esr:.3e} ({:.1} dB)",
        esr_to_db_f64(esr)
    );
    assert!(
        esr < 1e-12,
        "Rust oracle/Python anchor ESR {esr:.3e} exceeds 1e-12"
    );
}

#[test]
fn test_per_layer_kernels_live_cpp_parity() {
    let Some(render_bin) = require_render_or_skip("per-layer kernels c++ parity") else {
        return;
    };

    let input = input_f32();
    let json = fixture_json();
    let cpp = cpp_render_mono(&render_bin, &json, &input, 48_000, "per_layer_kernels");

    let data = parse_nam_json(&json).expect("parse model");
    let mut model = build_model(&data).expect("build model");
    model.prewarm(2048);
    let mut rust = vec![0.0f32; input.len()];
    process_in_blocks(model.as_mut(), &input, &mut rust);

    // The anchor/engine store starts from zero history while both production
    // paths prewarm; compare after the head transient.
    let start = 64;
    let esr = compute_esr(&cpp[start..], &rust[start..]);
    let snr = if esr > 0.0 {
        10.0 * (1.0 / esr).log10()
    } else {
        f64::INFINITY
    };
    eprintln!("[Geometry] {FIXTURE}: C++ vs Rust ESR={esr:.3e}, SNR={snr:.1} dB");
    assert!(esr < 1e-8, "C++/Rust ESR {esr:.3e} exceeds 1e-8");
    assert!(snr > 70.0, "C++/Rust SNR {snr:.1} dB below 70");
}

#[test]
fn test_per_layer_kernels_block_invariance_and_reset() {
    let input = input_f32();
    let data = parse_nam_json(&fixture_json()).expect("parse fixture");
    let mut model = build_model(&data).expect("build model");
    model.prewarm(2048);

    let mut whole = vec![0.0f32; input.len()];
    model.process(&input, &mut whole);

    model
        .reset(48_000, BLOCK)
        .expect("reset before blocked run");
    let mut blocked = vec![0.0f32; input.len()];
    let mut pos = 0;
    while pos < input.len() {
        let end = (pos + 1).min(input.len());
        model.process(&input[pos..end], &mut blocked[pos..end]);
        pos = end;
    }
    let block_esr = compute_esr(&whole, &blocked);
    eprintln!("[Geometry] {FIXTURE}: block-size invariance ESR={block_esr:.3e}");
    assert!(
        block_esr < 1e-10,
        "block-size invariance ESR {block_esr:.3e}"
    );

    model.reset(48_000, BLOCK).expect("reset");
    let mut after_reset = vec![0.0f32; input.len()];
    process_in_blocks(model.as_mut(), &input, &mut after_reset);
    let esr = compute_esr(&whole, &after_reset);
    eprintln!("[Geometry] {FIXTURE}: reset repeatability ESR={esr:.3e}");
    assert!(esr < 1e-12, "reset ESR {esr:.3e}");
}

#[test]
fn test_per_layer_kernels_zero_alloc_hot_path() {
    let data = parse_nam_json(&fixture_json()).expect("parse fixture");
    let mut model = build_model(&data).expect("build model");
    model.prewarm(2048);

    let input = generate_sine_440hz(BLOCK);
    let mut output = vec![0.0f32; BLOCK];

    {
        let _guard = TrackingGuard::new();
        model.process(&input, &mut output);
    }
    let allocs = get_alloc_count();
    assert_eq!(allocs, 0, "hot path allocated {allocs} times");
}

#[test]
fn test_per_layer_kernels_reject_ambiguous_and_mismatched() {
    let base = fixture_json();

    let mut both: serde_json::Value = serde_json::from_str(&base).expect("parse");
    both["config"]["layers"][0]
        .as_object_mut()
        .expect("layer")
        .insert("kernel_size".to_string(), serde_json::json!(3));
    let data = parse_nam_json(&both.to_string()).expect("ambiguous JSON must parse");
    assert!(
        matches!(
            get_wavenet_topology(&data),
            WavenetTopologyResult::Rejected { .. }
        ),
        "declaring kernel_size and kernel_sizes must be rejected"
    );

    let mut short: serde_json::Value = serde_json::from_str(&base).expect("parse");
    short["config"]["layers"][0]
        .as_object_mut()
        .expect("layer")
        .insert("kernel_sizes".to_string(), serde_json::json!([2, 3]));
    let data = parse_nam_json(&short.to_string()).expect("short JSON must parse");
    assert!(
        matches!(
            get_wavenet_topology(&data),
            WavenetTopologyResult::Rejected { .. }
        ),
        "kernel_sizes length mismatch must be rejected"
    );

    let mut zero: serde_json::Value = serde_json::from_str(&base).expect("parse");
    zero["config"]["layers"][0]["kernel_sizes"] = serde_json::json!([2, 0, 1]);
    let data = parse_nam_json(&zero.to_string()).expect("zero JSON must parse");
    assert!(
        matches!(
            get_wavenet_topology(&data),
            WavenetTopologyResult::Rejected { .. }
        ),
        "kernel_sizes with 0 must be rejected"
    );

    let mut hostile: serde_json::Value = serde_json::from_str(&base).expect("parse");
    hostile["config"]["layers"][0]["kernel_sizes"] = serde_json::json!([2, 3, 99]);
    let data = parse_nam_json(&hostile.to_string()).expect("hostile JSON must parse");
    assert!(
        matches!(
            get_wavenet_topology(&data),
            WavenetTopologyResult::Rejected { .. }
        ),
        "kernel_sizes above the ceiling must be rejected"
    );
}
